WITH payload AS (SELECT $archive_payload$[{"id":"c9e79910-ae16-50f7-b1f7-2df76374a9b9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي هيروين مخدر -تعاطي جرعة زائدة من املخدرات -إقرار املدعى عليه -إقامة حد املسكر على متعاطي الهيروين- التعزير باملنع من السفر .","document_number":"34278645","case_number":"34308204","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف تأجيل محاكمة األول حتى حضوره","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/24","year":"1434","subject":"مخدرات -تعاطي هيروين مخدر -تعاطي جرعة زائدة من املخدرات -إقرار املدعى عليه -إقامة حد املسكر على متعاطي الهيروين- التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34278645 :‬تاريخه ‪1434/7/24:‬هـ‬\n                         ‫رقم الدعوى‪34308204 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪       34351829‬تاريخه‪1434/11/5 :‬هـ‬\n\n\n\n      ‫مخــدرات ‪-‬تعاطــي هيرويــن مخــدر ‪ -‬تعاطــي جرعــة زائدة مــن املخدرات‬\n      ‫‪ -‬إقــرار املدعــى عليــه ‪ -‬إقامــة حــد املســكر علــى متعاطــي الهيرويــن‪-‬‬\n                                                  ‫التعزيــر باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n               ‫‪ -1‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                 ‫‪ -2‬املادة (‪ )3‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه الثاني واألول لــم يحضر بتعاطيه‬\n      ‫الهيرويــن املخــدر وطلــب املدعــي العــام تعزيــر املدعــى عليــه بالســجن‬\n      ‫واملنــع مــن الســفر وتشــديد العقوبــة بحقــه لقــاء كثــرة ســوابقه وتطبيــق‬\n      ‫املــواد (‪ ) 56/ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫بحقــه وحيــث أن املدعــى عليــه دخــل املستشــفى وهــو يف حالــة غيبوبــة‬\n      ‫أثــر تعاطيــه جرعــه زائــده مــن الهيرويــن وأثبــت التقريــر الكيميائــي‬\n      ‫لعينــة البــول اإليجابيــة ملــواد اإلمفيتامــن واملورفــن ‪ ،‬كمــا أقــر املدعــى‬\n      ‫عليــه بتعاطــي الهيرويــن املخــدر بنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n      ‫بإقامــة حــد املســكر علــى املدعــى عليــه نظــر ًا لتعاطيه الهيرويــن املخدر‬\n      ‫وتعزيــر املدعــى عليــه باملنــع مــن الســفر وصــرف النظــر عــن مقتضــى‬\n\n‫‪173‬‬\n\f‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬لــم يقنــع‬\n‫املدعــي العــام باحلكــم وطلــب رفعــه حملكمــة االســتئناف مكتفي ـ ًا‬\n‫مبــا قدمــه يف أوراق املعاملــة ‪ ،‬وقنــع املدعــى عليــه مبــا صــدر بحقــه مــن‬\n‫حكــم ‪  ،‬تصديــق احلكــم مــن محكمــة االســتئناف تأجيــل محاكمــة‬\n                                                          ‫األول حتــى حضــوره‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض    وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1434/07/04‬هــ  املقيــدة‬\n‫باحملكمــة برقــم ‪ ......‬وتاريــخ ‪ 1434/07/04‬هــ  ففــي يــوم  اإلثنــن‬\n‫املوافق‪1434/07/24‬ه ـ افتتحــت اجللســة الســاعة ‪  11 : 00‬وفيهــا قــدم‬\n‫املدعــي العــام ‪ ...‬دعــواه ‪ :‬وهــذا نصهــا فبصفتــي عضــو هيئــة التحقيــق‬\n                ‫واالدعــاء العــام مبدينــة الريــاض أدعــي علــى كل مــن‪:‬‬\n‫‪ ... )1‬ـ البالــغ مــن العمــر (‪ )37‬عام ـ ًا ـ ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة رقــم (‪ )...‬أعــزب‪ ،‬متعلــم‪ ،‬متقاعــد‪ ،‬يقيــم مبدينــة الريــاض‪،‬‬\n‫أوقــف بتاريــخ ‪1434/4/24‬ه ـ وأطلــق ســراحه بالكفالــة احلضوريــة‬\n‫بتاريــخ ‪1434/4/25‬ه ـ اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات‬\n                                                                      ‫اجلزائيــة‪.‬‬\n‫‪ .... )2‬ـ البالــغ مــن العمــر (‪ )51‬عامـ ًا ـ ســعودي اجلنســية مبوجــب الســجل‬\n‫املدني رقم (‪ )...‬أعزب‪ ،‬متعلم‪ ،‬متســبب‪ ،‬يقيم مبدينة الرياض‪ ،‬أوقف‬\n‫بتاريــخ ‪1434/4/24‬ه ـ وأطلــق ســراحه بالكفالــة احلضوريــة بتاريــخ‬\n‫‪1434/4/25‬ه ـ اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n\n                                                                                    ‫‪174‬‬\n\f      ‫حيــث إنــه بتاريــخ ‪1434/4/24‬هــ  تلقــي مركــز شــرطة العريجــاء‬\n      ‫اتصــا ًال مــن النقطــة األمنيــة مبستشــفى عــن وصــول املتهــم الثانــي الــذي‬\n      ‫مت إســعافه مــن قبــل الهــال األحمــر يف حالــة غيبوبــة لتعاطيــه جرعــة‬\n      ‫زائــدة مــن املخــدرات ويرافقــه املتهــم األول الــذي أفــاد بــأن املتهــم الثانــي‬\n      ‫قــام باستنشــاق مــادة الهيرويــن داخــل منزلــه‪ .‬وقــد ورد تقريــر طبي مرفق‬\n      ‫لفــه (‪ )4‬بتاريــخ ‪1434/4/24‬ه ـ يتضمــن أن املتهــم الثانــي يعانــي مــن‬\n      ‫غيبوبــه بســبب تعاطــي املخــدرات ويحتــاج إلــى تنــومي باملستشــفى‪ .‬كمــا‬\n      ‫ورد التقريــر الكيميائــي الشــرعي رقــم ‪ 5049‬املتضمــن ايجابيــة عينــة‬\n      ‫البــول املأخــوذة للثانــي‪ ...‬ملــادة االمفيتامــن وللمورفــن واالمفيتامــن مــن‬\n      ‫ضمــن املــواد املدرجــة بجــدول املــواد املخــدرة رقــم (‪)2‬فئــة (ب) واملورفــن‬\n      ‫ضمــن املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ ) 1‬فئــة (أ) وامللحقــة‬\n      ‫كليهمــا بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫بالرســوم امللكــي رقــم (م‪)39/‬يف ‪1426/7/8‬هـ‪.‬وبســماع أقــوال املتهــم‬\n      ‫األول األوليــة اعتــرف بتعاطــي الهيرويــن املخــدر ولــم يــدل مبعلومــات عــن‬\n      ‫مصــدره وأفــاد بــأن الثانــي قــام بإخــراج ظــرف بــه الهيرويــن املخــدر وقــام‬\n      ‫بشــمه يف منزلــه‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام‬\n      ‫لــأول ‪ ....‬والثانــي‪ ...‬بتعاطــي الهيرويــن املخــدر املجــرم مبوجــب املــادة‬\n      ‫(الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n                          ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n                                                           ‫وذلك لألدلة والقرائن التالية‬\n      ‫ا‬\n      ‫‪ )1‬مــا تضمنــه محضــر ســماع األقــوال األوليــة لــأول املنــوه عنــه تفصيـ ً‬\n                                                                               ‫يف املعاملــة‪.‬‬\n                                ‫‪ )2‬ما تضمنه محضر إثبات احلالة املنوه عنه املرفق‬\n\n\n‫‪175‬‬\n\f                                             ‫‪ )3‬ما تضمنه التقرير الطبي املرفق‪.‬‬\n                                     ‫‪ )4‬ماتضمنه التقرير الكيميائي الشرعي‪.‬‬\n‫ببحــث ســوابقهما عثــر للثانــي علــى ثــاث ســوابق األولــى حيــازة‬\n‫واســتعمال مخــدرات والثانيــة حيــازة واســتعمال مخــدرات والثالثــة حيازة‬\n‫أدوات اســتعمال مخــدرات‪ ،‬ولــم يعثــر لــأول علــى ســوابق مســجله حتــى‬\n                                                                             ‫تاريخــه‪.‬‬\n‫وحيــث أن مــا أق ــدم عل ــيه ال ــمذكور ف ــعل م ــحرم شــرع ًا وم ــعاقب عليــه‬\n‫شــرع ًا ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                              ‫باآلتــي‪:‬‬\n‫‪ )1‬إجــراء املقتضــى الشــرعي بحقهمــا وفق ـ ًا للفقــرة األولــى مــن املــادة‬\n                                                  ‫(‪ )41‬مــن النظــام املشــار إليــه‪.‬‬\n‫‪ )2‬مبنعهمــا مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة‬\n‫ســجنهما وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار‬\n                                                                                 ‫إليــه‪.‬‬\n‫‪ )3‬تشــديد العقوبــة بحــق الثانــي لقــاء كثــرة ســوابقه التــي لــم تردعــه‬\n‫عقوباتهــا وفق ـ ًا لبرقيــة صاحــب الســمو امللكــي نائــب وزيــر الداخليــة‬\n                           ‫رقــم (‪ )93958/5/5/1‬وتاريــخ ‪1429/8/23‬هــ‪.‬‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه الثانــي أجــاب قائــا ماذكــره‬\n‫املدعــي العــام مــن كونــي تعاطيــت الهيرويــن املخــدر فهــذا صحيــح وأنــا‬\n‫تائــب ونــادم وقــد راجعــت مشــفى األمــل للبــدء يف العــاج وعنــدي مايثبــت‬\n‫ذلــك وقــد جــرى تأمــل ماســبق فبنــاء علــى مــا ذكــره املدعــي العــام‬\n‫وحيــث أقــر املدعــى عليــه الثانــي بتعاطيــه للهيرويــن املخــدر وملــا جــاء يف‬\n‫التقريــر الكيميائــي املرفــق باملعاملــة لفــة رقــم (‪  )24‬فقــد حكمــت مبــا‬\n\n\n                                                                                           ‫‪176‬‬\n\f      ‫يلــي أوال ‪/‬جلــده احلــد ثمانــن جلــدة لقــاء تعاطيــه للهرويــن املخــدر  ثانيـاً‪/‬‬\n      ‫منعــه مــن الســفر خلــارج ملــدة ســنتني بنــاء علــى املــادة (‪ )3،56‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة ثالثـاً‪ /‬رددت طلــب املدعي العام‬\n      ‫بتطبيــق املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫لكــون القضيــة حديــة وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة‬\n      ‫باحلكــم كمــا قــرر املدعــي العــام عــدم القناعــة باحلكــم مكتفيــا مبــا‬\n      ‫قدمــه مــن أوراق وســيتم نظــر دعــوى املدعــى عليــه األول عنــد حضــوره‬\n      ‫واختتمــت اجللســة الســاعة ‪ .11:15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪1434/07/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n      ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم  وتاريــخ ‪1434/8/21‬ه ـ واملرفــق بها‬\n      ‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬برقــم وتاريــخ‬\n      ‫‪1434/7/24‬ه ـ واخلــاص بدعــوى املدعــي العــام ضــد ‪ ........‬ورفيقــه‪،‬‬\n      ‫وموضوعهــا مخــدرات ‪ ،‬وانتهــت الدراســة  والتدقيــق  باملصادقــة علــى‬\n      ‫احلكــم باألكثريــة لعــدم موجــب املالحظــة‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل‬\n                                ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪177‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":173,"source_page_end":177,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cf0e7b414b97d8e931ffef78eeae94709a23db1a53f68a174024722f069cbe0","normalized_text_hash":"35992f27c7b94a76c99f3833e2d004b1684c6a00466c60d4da4065c9f5f7d67e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p173-34278645"},{"id":"508fcb93-143b-55a8-b9fe-abc5c73aef5f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب اإلمفيتامن احملظورة -حيازة احلشيش املخدر -الهروب من الفرقة القابضة -إقرار -حد املسكر -التعزير باملنع من السفر -التعزير بالسجن لقاء الهروب من الفرقة القابضة -رد دعوى -تعليق محاكمة الغائب حلن القبض عليه.","document_number":"34306154","case_number":"34311632","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/9","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب اإلمفيتامن احملظورة -حيازة احلشيش املخدر -الهروب من الفرقة القابضة -إقرار -حد املسكر -التعزير باملنع من السفر -التعزير بالسجن لقاء الهروب من الفرقة القابضة -رد دعوى -تعليق محاكمة الغائب حلن القبض عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪  34306154 :‬تاريخه ‪1434/07/9 :‬هـ‬\n                    ‫رقم الدعوى‪34311632 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪      35282217‬تاريخه‪1435/6/17 :‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬تعاطــي احلبــوب اإلمفيتامــن‬\n‫احملظــورة ‪ -‬حيــازة احلشــيش املخــدر ‪ -‬الهــروب مــن الفرقــة القابضــة‬\n‫‪ -‬إقــرار ‪ -‬حــد املســكر ‪ -‬التعزيــر باملنــع مــن الســفر‪ -‬التعزيــر بالســجن‬\n‫لقــاء الهــروب مــن الفرقــة القابضــة ‪ -‬رد دعــوى ‪ -‬تعليــق محاكمــة‬\n                                              ‫الغائــب حلــن القبــض عليــه‪.‬‬\n\n\n\n           ‫‪-1‬قول النبي صلى اهلل عليه وسلم ‪ ( :‬كل مسكر حرام ) ‪.‬‬\n                                 ‫‪-2‬قاعدة ( املرء مؤاخذ بإقراره ) ‪.‬‬\n‫‪ -3‬مــا ذكــره أهــل العلــم مــن أن احلشــيش يشــترك مــع اخلمــر يف‬\n                                                    ‫منــاط احلكــم ‪.‬‬\n          ‫‪-4‬املادة (‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n        ‫‪-5‬املادة (‪ ) 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه األول بتعاطــي احلشــيش املخــدر‪،‬‬\n‫واحلبــوب احملظــورة‪ ،‬والهــروب مــن الفرقــة القابضــة‪ ،‬وحيــازة املدعــى‬\n‫عليــه  الثانــي  احلشــيش املخــدر‪ ،‬وتعاطيــه لنوعهــا‪ ،‬حيــث مت القبــض‬\n‫عليهمــا أثنــاء مســح الدائــري‪ ،‬وملــا مت إيقافهمــا هــرب املدعــى عليــه‬\n\n                                                                                  ‫‪178‬‬\n\f      ‫األول‪  ،‬ووجــد بالســيارة قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر‬\n      ‫وطلــب املدعــي العــام تعزيــر املدعــى عليهمــا بالســجن واملنــع مــن الســفر‬\n      ‫وتطبيــق املــواد (‪ ) 56/ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة بحقهمــا‪ ،‬واملــادة رقــم (‪ ) 30‬مــن الالئحــة التنفيذيــة لنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة بحــق املدعــى عليــه األول وتعزيــر املدعــى عليــه األول‬\n      ‫لقــاء هروبــه مــن رجــال األمــن ‪ ،‬كمــا أقــر املدعــى عليــه األول مبــا نســب‬\n      ‫إليــه ولــم يحضــر املدعــى عليــه الثانــي بنــاء علــى مــا ســبق حكمــت‬\n      ‫احملكمــة بحــد املســكر علــى املدعــى عليــه األول واحلكــم بالتعزيــر‬\n      ‫باملنــع مــن الســفر للمدعــى عليــه األول بنــاء علــى املــادة (‪ ) 56‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة و بتعزيــره بالســجن لقــاء هروبــه‬\n      ‫مــن رجــال األمــن‪ ،‬كمــا حكمــت بــرد دعــوى املدعــي العــام بخصــوص‬\n      ‫تطبيــق املــادة (‪ ) 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫بحــق املدعــى عليــه األول‪ ،‬تأجيــل احلكــم علــى املدعــى عليــه الثانــي‬\n      ‫حتــى حضــوره وقــرر املدعــى العــام اعتراضــه علــى احلكــم بــدون الئحة‪،‬‬\n      ‫فيمــا قنــع املدعــى عليــه مبــا صــدر بحقــه مــن حكــم وصــدق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪179‬‬\n\f‫اجلزائيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة‬\n‫باالحســاء  وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة  رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم  وتاريــخ ‪1434/07/05‬هـ  ‬\n‫املقيــدة باحملكمــة برقــم ‪ ......‬وتاريــخ ‪ 1434/07/05‬هــ  ففــي يــوم  ‬\n‫الســبت املوافق‪1434/08/13‬ه ـ افتتحــت اجللســة الســاعة ‪  11 : 00‬‬\n  ‫وفيهــا حضــر املدعــي العــام املعمــد بالترافــع أمــام هــذه احملكمــة‬\n  ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n  ‫االحســاء ذي الرقــم  والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضريــن‬\n  ‫معــه ‪ ......‬ســعودي اجلنســية مبوجــب ســجل املدنــي رقــم ‪ ....‬و ‪ ......‬ســعودي‬\n  ‫اجلنســية مبوجــب ســجل املدنــي رقــم ‪ ....‬إنــه بتاريــخ ‪1434/5/20‬ه ـ‬\n  ‫مت القبــض علــى املدعــى عليهمــا مــن قبــل الدوريــات األمنيــة مبوجــب‬\n  ‫احملضــر رقــم (‪ ).....‬وتاريــخ ‪1434/5/20‬ه ـ وذلــك أثنــاء مســح الدائــري‬\n  ‫حيــث مت إيقــاف املركبــة مــن نــوع (‪ ).....‬والتــي حتمــل اللوحــة (‪)....‬‬\n‫والتــي بقيــادة املدعــى عليــه‪ ......‬وعنــد التأكــد مــن املدعــى عليهمــا‬\n‫قــام املدعــى عليــه‪  ......‬بالهــرب فتــم القبــض عليــه‪ ،‬وبتفتيــش املركبــة‬\n‫ضبــط عنــد بــاب املرافــق علــى علبــة ســجائر بداخلهــا فتــات ســجائر‬\n‫يحتمــل أنهــا مخلوطــة باحلشــيش املخــدر تــزن (‪ )0.1‬واحــد مــن العشــرة‬\n‫مــن اجلــرام حيــث أقــر املدعــى عليــه‪ ......‬أنهــا تعــود لــه‪ .‬وقــد أثبــت التقريــر‬\n‫الكيميائــي الشــرعي رقــم (‪ 2559‬ك ش) إيجابيــة الفتــات املضبــوط‬\n‫للمــادة احلشــيش املخــدر املــدرج يف اجلــدول األول فئــة (أ) امللحــق بنظــام‬\n‫مكافحــة املخــدرات ‪ ،‬و أثبــت تقريــر الســموم الشــرعي رقــم (‪ 873‬م أ)‬\n\n                                                                                             ‫‪180‬‬\n\f        ‫إيجابيــة عينــة الســوائل املأخــوذة مــن  املدعــى عليــه‪ ......‬ملــادة احلشــيش‬\n        ‫املخــدر املــدرج يف اجلــدول األول فئــة (أ) امللحــق بنظــام مكافحــة‬\n        ‫املخــدرات‪ .‬وبســماع أقــوال املدعــى عليــه ‪ ......‬أقــر بتعاطيــه للحبــوب‬\n        ‫احملظــورة يف الســابق ‪ .‬وبســماع أقــوال املدعــى عليــه ‪ ......‬أقــر بحيازتــه‬\n        ‫للحشــيش املخــدر لقصــد التعاطــي وتعاطيــه لنوعــه ‪ ،‬كمــا أفصــح عــن‬\n        ‫مصــدر املضبوطــات ‪ .‬وانتهــى التحقيــق معهمــا إلــى توجيــه االتهــام لــأول‬\n        ‫بتعاطــي احلشــيش املخــدر و احلبــوب احملظــورة يف الســابق‪ ،‬وتوجيــه‬\n      ‫االتهــام للثانــي بحيــازة مــا وزنــه (‪ )0.1‬واحــد مــن العشــرة مــن اجلــرام  ‬\n        ‫لقصــد التعاطــي وتعاطيــه لنوعهــا املجرمــة يف ضــوء الفقــرة الثانيــة مــن‬\n        ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n        ‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬وبهرب‬\n        ‫املدعــى عليــه األول مــن الفرقــة القابضــة أثنــاء القبــض عليــه ‪.‬وذلــك‬\n                                                             ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n        ‫‪ -1‬مــا جــاء يف أقــوال املدعــى عليهمــا املنــوه عنهــا ‪ ،‬املدونــة  يف الصفحــة‬\n                                                                        ‫رقم (‪.)6-5-4-3‬‬\n                            ‫‪ -2‬محضر القبض والتفتيش املرفق على اللفة رقم (‪.)5‬‬\n                                ‫‪ -3‬التقرير الكيميائي املرفق على اللفة رقم (‪.)31‬‬\n                             ‫‪ -4‬تقرير السموم الشرعي املرفق على اللفة رقم (‪.)33‬‬\n        ‫حيــث إن مــا أقــدم عليــه املدعــى عليهمــا املذكــوران ـ وهمــا بكامــل‬\n        ‫أهليتهمــا املعتبــرة شــرع ًا ـ فعــل محــرم ومجــرم معاقــب عليــه شــرع ًا‬\n        ‫ونظامـ ًا ؛ لــذا أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا مبــا يلــي ‪:‬‬\n                                                                                         ‫أوالً‪:‬‬\n        ‫‪-1‬معاقبــة املدعــى عليــه األول بالعقوبــة الــواردة يف الفقــرة األولــى مــن‬\n\n\n‫‪181‬‬\n\f‫املــادة ( ‪ ) 41‬مــن النظــام املشــار إليــه أعــاه ‪ ،‬و املــادة (‪ )30‬مــن الالئحــة‬\n‫التنفيذيــة لــذات النظــام املشــار إليــه أعــاه لقــاء مــا أســند إليــه مــن اتهــام‬\n‫‪-2.‬معاقبــة املدعــى عليــه الثانــي بالعقوبــة الــواردة يف الفقــرة األولــى مــن‬\n‫املــادة ( ‪ ) 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا‬\n                                                               ‫أســند إليــه مــن اتهــام ‪.‬‬\n‫‪-3‬تطبيــق مــا جــاء يف الفقــرة األولــى مــن املــادة ( ‪ ) 56‬مــن ذات النظــام‬\n                                ‫وذلــك مبنعهمــا مــن الســفر إلــى خــارج البــاد ‪.‬‬\n                                                                                     ‫ثانياً‪:‬‬\n‫‪-1‬معاقبــة املدعــى عليــه األول بعقوبــة تعزيريــة لقــاء هروبــه مــن الفرقــة‬\n                                                     ‫القابضــة أثنــاء القبــض عليــه ‪.‬‬\n‫‪-2‬تشــديد العقوبــة علــى املدعــى عليهمــا كونهمــا رجــا أمــن منــوط‬\n‫بهمــا حفــظ األمــن ال مخالفتــه اســتناد ًا لتعميــم وزيــر الداخليــة رقــم‬\n                                            ‫(‪ )52170‬وتاريــخ ‪1432/8/15‬ه ـ ‪.‬‬\n‫ا مــا ذكــره‬     ‫هــذه دعــواي وبســؤال املدعــى عليــه االول أجــاب قائ ـ ً‬\n‫املدعــي العــام مــن أنــه بتاريــخ ‪1434/5/20‬ه ـ مت إيقــاف الســيارة نــوع‬\n‫‪  .......‬والتــي تعــود للمدعــى عليــه الثانــي مــن قبــل الدوريــات األمنيــة‬\n‫وأنــه مت تفتيشــها وأنــه عثــر فيهــا علــى علبــة ســجائر بداخلهــا فتــات‬\n‫ســجائر مخلوطــة باحلشــيش يــزن واحــد مــن العشــرة مــن اجلــرام تعــود‬\n‫للمدعــى عليــه الثانــي والــذي أقــر بذلــك فهــذا كلــه صحيــح وكذلــك‬\n‫مــا ذكــره املدعــي العــام مــن أننــي هربــت فصحيــح حيــث إنــه لــم يكــن‬\n‫معــي إثبــات ممــا دعانــي للهــرب وكذلــك مــا ذكــره املدعــي العــام مــن‬\n‫أنــه مت التحليــل وأن نتيجــة التحليــل أظهــرت اســتخدامي للحشــيش‬\n‫املخــدر فهــذا كلــه صحيــح هكــذا أجــاب وبنــاء عليــه فقــد مت رفــع‬\n\n\n                                                                                               ‫‪182‬‬\n\f        ‫اجللســة النتهــاء وقتهــا وإلــى حــن حضــور املدعــى عليــه الثانــي ويف يــوم‬\n      ‫اخلميــس املوافــق ‪1434/08/25‬ه ـ افتتحــت اجللســة الســاعة ‪  10 : 15‬‬\n        ‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه األول ولــم يحضــر املدعــى‬\n        ‫عليــه الثانــي  وباإلطــاع علــى املعاملــة وجــد فيهــا علــى لفــة رقــم ‪31‬‬\n        ‫تقريــر الســموم الشــرعية رقــم ‪/873‬أ واملتضمــن إيجابيــة عينــة البــول‬\n        ‫املرســلة ملركبــات احلشــيش املخــدر واحملظــور دولي ـ ًا أ‪ .‬ه ـ فبنــاء علــى‬\n        ‫مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه األول وحيــث إن‬\n        ‫املــرء مؤاخــذ بإقــراره ولتقريــر الســموم الشــرعية ولقــول النبــي صلــى‬\n        ‫اهلل عليــه وســلم كل مســكر حــرام وحيــث إن احلشــيش يشــترك مــع‬\n        ‫اخلمــر يف منــاط احلكــم لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n        ‫عليــه األول  بتعاطــي احلشــيش املخــدر و احلبــوب احملظــورة يف الســابق‬\n        ‫وهروبــه مــن الفرقــة القابضــة أثنــاء القبــض عليــه وحكمــت عليــه مبــا‬\n        ‫يلــي ‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه األول ‪ .....‬ثمانــن جلــدة دفعــة واحــدة‬\n        ‫حــد املســكر ثاني ـ ًا ‪ :‬منــع املدعــى عليــه األول ‪ .......‬مــن الســفر خــارج‬\n        ‫اململكــة مــدة ســنتني بعــد تنفيــذ العقوبــة اســتناد ًا للفقــرة (‪ )1‬مــن املــادة‬\n        ‫(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ثالث ـ ًا ‪ :‬ســجن‬\n        ‫املدعــى عليــه مــدة شــهر حتتســب منهــا مــدة بقائــه بالســجن بخصــوص‬\n        ‫هــذه القضيــة لقــاء هروبــه مــن رجــال األمــن أثنــاء القبــض عليــه رابعـ ًا ‪:‬‬\n        ‫رد دعــوى املدعــي العــام بخصــوص عقوبــة املدعــى عليــه األول بالعقوبــة‬\n        ‫الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n        ‫واملؤثــرات العقليــة وذلــك لعــدم ثبوتهــا وأمــا املدعــى عليــه الثانــي فســوف‬\n        ‫يتــم تأجيــل احلكــم عليــه إلــى حــن القبــض عليــه هــذا مــا ظهــر لــي وبــه‬\n        ‫حكمــت وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه األول‬\n\n\n‫‪183‬‬\n\f  ‫قــرر املدعــي العــام اعتراضــه عليــه وطلــب رفــع املعاملــة إلــى محكمــة‬\n  ‫االســتئناف بــدون الئحــة فأجبتــه لطلبــه وأمــا املدعــى عليــه األول قــرر‬\n  ‫عــدم االعتــراض عليــه وبــه ختمــت اجللســة يف متــام الســاعة ‪ 10 : 30‬وباهلل‬\n  ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف  ‪1434/08/25‬ه ـ‬\n  ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n  ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n  ‫املقيــدة لــدى احملكمــة برقــم وتاريــخ ‪1434/9/9‬ه ـ الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف برقــم ‪  ......‬‬\n  ‫وتاريــخ ‪1434/9/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n  ‫باحملكمــة الشــيخ ‪ ......‬املســجل برقــم ‪  ......‬وتاريــخ ‪1434/8/25‬ه ـ‬\n  ‫اخلــاص بدعــوى ‪ ......‬املدعــي العــام ضــد ‪ ......‬كل مــن ‪ /2 /1‬يف قضيــة‬\n  ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n  ‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n  ‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                 ‫وســلم‪ .‬حــرر يف ‪1434/9/17‬هــ‪.‬‬\n\n\n\n\n                                                                                           ‫‪184‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":178,"source_page_end":184,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2552082947131338d7d596bdd1ffda7677c64d0a5d4695a94d9aa79a2fb0bb27","normalized_text_hash":"c5c541fd97739eced8734016545bec004b9b3a3d092b85da27d130819932127b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p178-34306154"},{"id":"f5ceb587-bc7d-5113-9dc5-6fb2e08ec03f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -حيازة احلشيش املخدر -حيازة حبوب الترامادول -التستر على مصدر املخدرات -إقرار إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واإلبعاد عن الباد -رد دعوى املدعي العام بخصوص التستر.","document_number":"34275870","case_number":"34321084","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"مخدرات -تعاطي مخدرات -حيازة احلشيش املخدر -حيازة حبوب الترامادول -التستر على مصدر املخدرات -إقرار إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واإلبعاد عن الباد -رد دعوى املدعي العام بخصوص التستر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪  34275870 :‬تاريخه ‪1434/7/23:‬هـ‬\n                          ‫رقم الدعوى‪34321084 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪  34296891‬تاريخه‪1434/8/14  :‬هـ‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬حيــازة احلشــيش املخــدر ‪ -‬حيازة حبوب‬\n      ‫الترامــادول ‪ -‬التســتر علــى مصــدر املخــدرات ‪ -‬إقــرار إقامــة حــد املســكر‬\n      ‫علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واإلبعــاد عــن البــاد ‪ -‬رد‬\n                                          ‫دعــوى املدعــي العــام بخصــوص التســتر‪.‬‬\n\n\n\n              ‫‪ -1‬قوله تعالى( وال تقتلوا النفس التي حرم اهلل إال باحلق ) ‪.‬‬\n                   ‫‪ -2‬قوله تعالى ( و ال تفسدوا يف األرض بعد إصالحها ) ‪.‬‬\n                ‫‪ -3‬املادة(‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                ‫‪ -4‬املادة(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n               ‫‪ -5‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قطعــة مــن احلشــيش‬\n      ‫وتعاطــي احلشــيش املخــدر وتعاطــي حبــوب الترامــادول وتســتره علــى‬\n      ‫مصــدر احلشــيش املخــدر‪ ،‬وطلــب معاقبــة املدعــى عليــه وفــق نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وتعزيــرة علــى التســتر حيــث‬\n      ‫أنــه قــد مت اســتيقاف املدعــى عليــه وهــو يقــود ســيارته‪ ،‬وبانــت عليــه‬\n      ‫عالمــات االرتبــاك‪ ،‬وبتفتيــش الســيارة  وجــد قطعــة يشــتبه أن تكــون‬\n\n‫‪185‬‬\n\f‫مــن احلشــيش املخــدر واعتــرف بتعاطــي حبــوب الترامــادول يف الســابق‪،‬‬\n‫إقــرار املدعــى عليــه مبــا نســب إليــه وأظهــر للمحكمــة النــدم‪ ،‬بنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بإقامــة حــد املســكر علــى املدعــى‬\n‫عليــه لقــاء تعاطيــه احلشــيش املخــدر وســجنه بنــاء علــى املــادة (‪ )41‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقلية‪،‬إبعــاده عــن اململكــة‬\n‫العربيــة الســعودية وال يســمح بالعــودة إليهــا إال فيمــا تســمح بــه تعليمــات‬\n‫احلــج والعمــرة ‪ ،‬بنــاء علــى املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة‪ ،‬والنــزول عــن احلــد األدنــى للعقوبــة بنــاء علــى املــادة‬\n‫(‪ )60‬وعــدم ثبــوت اإلدانــة بالتســتر ‪ -‬قــرر املدعــى عليــه اعتراضــه علــى‬\n‫احلكــم بــدون الئحــة‪ ،‬وقنــع املدعــى عليــه مبــا صــدر بحقــه مــن حكــم‬\n                                 ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n  ‫ـدي‬\n   ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n  ‫ـاء علــى املعاملــة‬     ‫أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة باألحســاء   بنـ ً‬\n  ‫الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ‪ 10435‬وتاريــخ ‪1434/7/10‬ه ـ واملقيــدة بهــذه احملكمــة برقــم  ‬\n  ‫‪ ......‬وتاريــخ ‪1434/7/11‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس برقــم‬\n  ‫وتاريــخ ‪1434/7/11‬ه ـ فتحــت اجللســة األولــى يــوم األربعــاء تاريــخ‬\n  ‫‪1434/7/19‬ه ـ الســاعة التاســعة وفيهــا حضــر املدعــي العــام ‪ ...‬امل َُع ّمــد‬\n  ‫بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة‬\n‫التحقيــق واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم ‪ 13415‬والتاريخ  ‬\n  ‫‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـاً‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬\n\n                                                                                         ‫‪186‬‬\n\f      ‫اإلدعــاء العــام لدائــرة التحقيــق واالدعــاء العــام مبحافظــة االحســاء‬\n      ‫أدعــي علــى‪ ...‬مصــري اجلنســية مبوجــب رخــص واإلقامــة رقــم ‪ ....‬البالــغ‬\n      ‫مــن العمــر ‪ 37‬عام ـ ًا احلالــة االجتماعيــة متــزوج باالطــاع علــى محضــر‬\n      ‫القبــض املعــد مــن قبــل رجــال دوريــات أمــن الطــرق برقــم (‪ )9213‬تبــن‬\n      ‫أنــه بتاريــخ ‪1434/6/9‬ه ـ وأثنــاء قيــام الدوريــات األمنيــة بعملهــا علــى‬\n      ‫طريــق اجلبــل باجتــاه اجلنــوب‪ ،‬مت اســتيقاف ســيارة مــن نــوع (‪ )......‬ســنة‬\n                   ‫الصنــع ( ‪2013‬م ) حتمــل اللوحــة (‪ )...‬بقيــادة املدعــى عليــه ‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ 2861‬ك ش) لعــام‬\n      ‫‪1434‬ه ـ الصــادر مــن املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة‬\n      ‫الشــرقية إيجابيــة عينــة القطعــة املضبوطــة   ملــادة احلشــيش املخــدر‬\n      ‫واملــدرج يف اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة‪ .‬وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبض‬\n      ‫والضبــط‪ ،‬وشــرائه للقطعــة املضبوطــة مــن شــخص ال يعرفــه‪ ،‬وحيازتــه‬\n      ‫لهــا بقصــد التعاطــي ‪ ،‬وتعاطيــه للحشــيش املخــدر يف الســابق وحلبــوب‬\n                                                                   ‫الترامــادول احملظــور ‪.‬‬\n      ‫وانتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بحيــازة قطعــة مــن احلشــيش‬\n      ‫املخــدر تــزن (‪ )2،5‬جرامــن وخمســة أعشــار اجلــرام بقصــد التعاطــي‬\n      ‫وتعاطيــه لنوعــه وحلبــوب الترامــادول احملظــور يف الســابق‪ ،‬املجــرم‬\n      ‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n            ‫وتســتره علــى مصــدر املخــدرات وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ -1‬مــا جــاء يف إقــراره املنــوه عنــه ‪ ،‬املــدون علــى الصفحتــن رقــم (‪)2،1‬‬\n                                                   ‫مــن دفتــر التحقيــق لفــه رقــم(‪. )......‬‬\n\n\n‫‪187‬‬\n\f                        ‫‪ -2‬ما جاء يف محضر القبض املرفق لفة رقم (‪.)12‬‬\n                 ‫‪ -3‬ما جاء يف التقرير الكيماوي املرفق لفة رقم ( ‪.) 11‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا ‪ ،‬فعــل مجــرم ومعاقــب علي ــه نظامـ ًا ؛ لــذا أطلــب إثبــات مــا أســند‬\n                                                  ‫إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪ -1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظــام املشــار‬\n                                                          ‫إليــه لقــاء مــا أســند إليــه‪.‬‬\n‫‪ -2‬بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة (‪ )56‬من النظام املشــار‬\n                             ‫إليــه بإبعــاده عــن البــاد بعد تنفيــذ محكوميته‪.‬‬\n                      ‫‪ -3‬بعقوبة تعزيرية لقاء تستره على مصدر املخدرات‪.‬‬\n‫هكــذا ا َّدعــى؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن‬\n‫هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـاً‪ :‬صحيــح‬\n‫مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض ومــن حيازتــي لقطعــة‬\n‫احلشــيش املخــدر البالــغ وزنهــا (‪ )2،5‬جرامــان وخمســة أعشــار اجلــرام‬\n‫بقصــد التعاطــي ومــن اســتعمالي  للحشــيش املخــدر وحلبــوب الترامــدول‬\n‫احملظــورة وصحيــح اعتــرايف وغيــر صحيــح تســتري علــى مصــدر‬\n‫املخــدرات فقــد أخبــرت جهــة التحقيــق أننــي اشــتريتها مــن شــخص‬\n‫ال أعرفــه هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام هــل لديــه‬\n‫ـدي ســوى مــا يف أوراق‬  ‫بينــة علــى مــا نفــاه املدعــى عليــه فقــال‪ :‬ليــس لـ َّ‬\n‫املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب فجــرى االطــاع علــى‬\n‫جميــع أوراق املعاملــة ومنهــا‪ :‬التقريــر الكيمــاوي الشــرعي الصــادر مــن‬\n‫قســم الكيميــاء الشــرعية باملركــز اإلقليمــي ملراقبــة الســموم التابــع‬\n‫للمديريــة العامــة للشــؤون الصحيــة باملنطقــة الشــرقية برقــم (‪ 2861‬ك‬\n\n\n                                                                                              ‫‪188‬‬\n\f      ‫ش) لعــام  ‪14343‬ه ـ املتضمــن إيجابيــة عي ــنة مــا ضبط للحشــيش املخدر  ‬\n        ‫كمــا  جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن خلــوه‬\n        ‫مــن الســوابق كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n        ‫املتضمنــة أنــه أوقــف بتاريــخ ‪1434/06/09‬هــ  فبنــاء علــى مــا ورد مــن‬\n        ‫الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن‬\n      ‫أهليتــه  وملــا ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه  ‬\n        ‫صــادق علــى صحــة مــا نســب إليــه مــن  حيــازة  احلشــيش علــى صفــة‬\n      ‫مــا ورد يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا يف  ‬\n        ‫احلشــيش املخــدر مــن اخلطــر والضــرر علــى  البــاد  والعبــاد وعلــى مــن‬\n        ‫صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم اهلل إال باحلــق)‬\n        ‫وقــال (وال تفســدوا يف األرض بعــد إصالحهــا ) ممــا يســتوجب معاقبــة‬\n        ‫املدعــى عليــه  و تعزيــزه بالعقوبــة الــواردة يف املــادة الواحــدة واألربعني من‬\n        ‫نظــام مكافحــة املخــدرات ويتوجــه أن يكــون أقــل عقوبــة  ملــا ظهــر مــن‬\n      ‫حالــه مــن النــدم وألنــه ال ســوابق لــه ولقلــة الكميــة التــي وجــدت بحيازته  ‬\n      ‫كمــا يتوجــه تخفيــف تلــك العقوبــة أيضــا حســب مقتضــى املــادة  الســتني  ‬\n        ‫مــن النظــام نفســه ملــا ظهــر مــن حالــه مــن  النــدم ولظروفــه االجتماعيــة‬\n        ‫التــي اقتنعــت بهــا احملكمــة وألنــه ال ســوابق لــه كمــا يتوجــه اســتحقاقه‬\n        ‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة الثانيــة منهــا ومبــا‬\n        ‫أن املدعــى عليــه أقـ َّـر باســتعمال احلشــيش املخــدر واســتعماله يأخــذ‬        ‫َّ‬\n        ‫حكــم املســكر للتوافــق بينهمــا يف منــاط  احلكــم وحــد املســكر أن‬\n        ‫يجلــد صاحبــه ثمانــن جلــدة علنــا كمــا اســتقر عليــه عمــل األمــة ممــا‬\n        ‫يتوجــب حــد املدعــى عليــه حــد املســكر الســتعماله للحشــيش املخــدر‬\n        ‫واالكتفــاء عــن مجازاتــه عــن اســتعمال احلبــوب لدخــول األصغــر يف‬\n\n\n‫‪189‬‬\n\f‫أن املدعــى عليــه أنكــر دعــوى املدعــي العــام‬          ‫حكــم األكبــر‪ .‬ومبــا َّ‬\n‫باتهامــه بالتســتر علــى مصــدر املخــدرات وال بينــة للمدعــي العــام علــى‬\n‫ذلــك ممــا يســتوجب ر َّد دعــوى املدعــي العــام بإثبــات إدانــة املدعــى عليــه‬\n‫بذلــك  لــذا كلــه وألجــل احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي‪:‬‬\n‫ـدي إدانــة املدعــى عليــه باســتعمال احلشــيش املخــدر ويجلــد‬        ‫أوالً‪ /‬ثبــت لـ َّ‬\n‫ـدي إدانتــه‬\n          ‫حــد املســكر ثمانــن جلــدة دفعــة واحــدة علن ـ ًا كمــا ثبــت لـ َّ‬\n‫باســتعمال حبــوب الترامــدول احملظــور وعقوبتــه لقــاء ذلــك داخلــة يف‬\n‫عقوبــة احلشــيش‪ .‬ثانيـاً‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة احلشــيش‬\n‫املخــدر املوصــوف يف  الدعــوى البالــغ وزنــه (‪ )2،5‬جرامــان وخمســة‬\n‫أعشــار اجلــرام بقصــد التعاطــي وأن يعــزر بســجنه ثالثــة أشــهر مــن تاريــخ‬\n‫توقيفــه علــى ذمــة القضيــة وذلــك مبوجــب املــادة الواحــدة و األربعــن مــن‬\n‫نظام مكافحة املخدرات واملادة الستني ‪ .‬ثالثاً‪ /‬وأن يبعد عن اململكة‬\n‫بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه واســتيفاء مــا لــه ومــا عليــه مــن‬\n‫حقــوق وال يســمح لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح بــه تعليمــات‬\n‫احلــج والعمــرة حســب مقتضــى مــا ورد يف املــادة السادســة واخلمســن مــن‬\n‫ـدي إدانــة املدعــى عليــه‬‫النظــام نفســه الفقــرة الثانيــة‪ .‬رابعـاً‪ /‬لــم يثبــت لـ َّ‬\n‫بالتســتر علــى مصــدر املخــدرات وقــررت ر َّد دعــوى املدعــي العــام بإثبــات‬\n‫إدانتــه بذلــك وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه‬\n‫يف االســتئناف قــرر قناعتــه باحلكــم وطلــب املدعــي العــام رفــع احلكــم‬\n‫لالســتئناف وأن الئحتــه االعتراضيــة هــي الئحــة الدعــوى هــذا وجــرى‬\n‫توجيــه املدعــى عليــه  مبــا يلــزم ومــن ذلــك حرمــة اســتعمال احلشــيش‬\n‫املخــدر واحلبــوب احملظــورة  وأثــره الســيئ علــى العقــل واملــال وأقفلــت‬\n‫اجللســة الســاعة التاســعة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n\n\n                                                                                             ‫‪190‬‬\n\f               ‫وعلــى آلــه وصحبــه أجمعــن  حــرر احلكــم يف ‪1434/07/19‬ه ـ ‪.‬‬\n        ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n        ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف  ‬\n        ‫برقــم وتاريــخ ‪1434/8/1‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪ ......‬وتاريــخ‬\n        ‫‪1434/8/7‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ  ‪  ....‬املســجل برقــم ‪ ......‬وتاريــخ ‪1434/7/23‬هــ  ‬\n        ‫اخلــاص بدعــوى‪ ....‬املدعــي العــام ضــد ‪ ....‬مصــري اجلنســية يف قضيــة‬\n        ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n        ‫فيــه‪ .‬وبدراســة  القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n        ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                         ‫وســلم حرريف‪1434/8/13‬ه ـ ‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":185,"source_page_end":191,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"21cc6e6c073967d5f232ac48ac4fba3de5594a63ea3eebc234037490afb2aa67","normalized_text_hash":"67e49aff720d432f84798402c5655b2f3a8cbb7be968605e8e62547e964b34db","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p185-34275870"},{"id":"4c66b1e2-776f-5b85-a4aa-3fb971f21217","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -حيازة احلشيش املخدر بقصد التعاطي -إقرار -إقامة حد املسكر على متعاطي احلشيش - التعزير بالسجن واإلبعاد عن الباد.","document_number":"34270509","case_number":"34324259","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية االولى (ج )1/برقم وتاريخ 1434/08/08ه املتضمن","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"مخدرات -تعاطي مخدرات -حيازة احلشيش املخدر بقصد التعاطي -إقرار -إقامة حد املسكر على متعاطي احلشيش - التعزير بالسجن واإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34270509 :‬تاريخه ‪1434/7/17:‬هـ‬\n                   ‫رقم الدعوى‪34324259 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪     34352841‬تاريخه‪1434/11/6:‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬حيــازة احلشــيش املخــدر بقصــد‬\n‫التعاطــي ‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪-‬‬\n                        ‫التعزيــر بالســجن واإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n        ‫‪ -1‬قولة تعالى( وال تقتلوا النفس التي حرم اهلل إال باحلق ) ‪.‬‬\n              ‫‪ -2‬قولة تعالى ( و ال تفسدوا يف األرض بعد إصالحها ) ‪.‬‬\n‫‪ -3‬مــا ذكــره أهــل العلــم مــن أن احلشــيش يأخــذ حكــم املســكر للتوافــق‬\n            ‫بينهمــا يف منــاط احلكــم ‪ ،‬كمــا اســتقر عليــه عمــل األمــة ‪.‬‬\n         ‫‪ -4‬املادة (‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n         ‫‪ -5‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n         ‫‪ -6‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليه بحيازة احلشــيش املخــدر وتعاطيه‬\n‫احلشــيش املخــدر وتســتره علــى مصــدر املخــدرات وطلــب املدعــى العــام‬\n‫معاقبــة املدعــى عليــه لقــاء تعاطيــه احلشــيش املخــدر‪ ،‬طلب املدعــي العام‬\n‫ســجن املدعــى عليــه وتســفيره إلــى بــاده بنــاء علــى املــواد (  ‪) 56/ 41‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬أقــر املدعــى عليــه‬\n\n                                                                                 ‫‪192‬‬\n\f      ‫مبــا جــاء يف دعــوى املدعــي العــام حيــث أنــه مت اســتيقاف املدعــى عليــه‬\n      ‫وبقيادتــه ســيارة وظهــر عليــه عالمــات االرتبــاك وبتفتيــش الســيارة وجــد‬\n      ‫قطعــة يشــتبه أن تكــون مــن احلشــيش املخدر‪،‬بنــاء علــى ذلــك حكمــت‬\n      ‫احملكمــة بإقامــة حــد املســكر بحــق املدعــى عليــه واحلكــم بتعزيــر‬\n      ‫املدعــى عليــه بالســجن واإلبعــاد عــن اململكــة العربيــة الســعودية وال‬\n      ‫يســمح بالعــودة إليهــا إال فيمــا تســمح بــه تعليمــات احلــج والعمــرة‪ ،‬فقــرر‬\n      ‫املدعــى عليــه اعتراضــه علــى احلكــم بــدون الئحــة ‪ ،‬وقنــع املدعــى عليــه‬\n      ‫مبــا صــدر بحقــه مــن حكــم وصــدق احلكــم مــن محكمــة االســتئناف  ‪.‬‬\n\n\n\n\n      ‫ـدي‬\n        ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n      ‫ـاء علــى املعاملــة‬  ‫أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة باألحســاء  بنـ ً‬\n      ‫الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء‬\n      ‫برقــم ‪  ......‬وتاريــخ ‪1434/7/10‬ه ـ واملقيــدة بهــذه احملكمــة برقــم  ‪......‬‬\n      ‫وتاريــخ ‪1434/7/12‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس برقــم وتاريــخ‬\n      ‫‪1434/7/12‬ه ـ فتحــت اجللســة األولــى يــوم االثنــن ‪1434/7/17‬ه ـ‬\n      ‫الســاعة الثانيــة والنصــف وفيهــا حضــر املدعــي العــام امل َُع ّمــد بالترافــع‬\n      ‫أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق‬\n      ‫واإلدعاء العام مبحافظة األحساء ذي الرقم  والتاريخ  ‪1433/12/01‬هـ‬\n      ‫وقـ ّـرر دعــواه قائـاً‪ :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لدائــرة‬\n      ‫التحقيــق واالدعــاء العــام مبحافظــة االحســاء أدعــي علــى ‪ ، ......‬اجلنــس‬\n      ‫ذكــر‪ ،‬اجلنســية االردن ‪ ،‬مســلم الديانــة ‪ ،‬العمــر ‪ 27‬عامــا ‪ ،‬رقــم‬\n      ‫االقامــة (‪ ).....‬جهــة االصــدار جــوازات الريــاض املهنــة موظــف اهلــي‬\n\n‫‪193‬‬\n\f‫احلالــة االجتماعيــة اعــزب مــكان االقامــة الريــاض جهــة االيقــاف ســجن‬\n‫االحســاء تاريــخ القبــض ‪1434/06/09‬ه ـ حالــة املتهــم موقــوف االتهــام‬\n‫شــراء املــواد املخــدرة وتعاطــي املــواد املخدرة وحيازة مــواد مخدرة بقصد‬\n‫التعاطــي واالســتعمال الســوابق ال يوجــد فباالطــاع علــى محضــر تنفيــذ‬\n‫مهمــة رقــم (‪ ).....‬و تاريــخ ‪1434/6/9‬ه ـ املعــد مــن دوريــات أمــن الطــرق‬\n‫بطريــق الدمــام الريــاض الســريع ويف مركــز الضبــط األمنــي التابــع لــه‬\n‫مت اســتيقاف ســيارة مــن نــوع (‪ ).......‬حتمــل اللوحــة رقــم (‪ )......‬بيضــاء‬\n‫اللــون بقيــادة املدعــى عليــه والحظــوا عليــه عالمــات االرتبــاك وبتفتيــش‬\n‫الســيارة ضبطــت قطعــة تــزن (‪ )1.5‬غــرام وخمســة أعشــار الغــرام يشــتبه‬\n                   ‫أن تكــون مــن احلشــيش املخــدر بداخــل حقيبــة مالبــس‪.‬‬\n‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ )......‬لعــام ‪1434‬ه ـ‬\n‫إيجابيــة عينــة القطعــة املضبوطــة ملــادة احلشــيش املخــدر و املــدرج يف‬\n‫اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫    وباســتجواب املدعــى عليــه  ‪ -‬وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫و بشــراء و حيــازة قطعــة تــزن (‪ )1.5‬غــرام وخمســة أعشــار الغــرام مــن‬\n‫احلشــيش املخــدر لقصــد االســتعمال الشــخصي وتعاطيــه لنوعــه يف‬\n                                    ‫الســابق  وتســتره علــى مصــدر املخــدرات‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬اعترافــه املــدون علــى الصفحــة رقــم (‪ )3‬مــن ملــف التحقيــق املرفــق‬\n                                                                       ‫لفــة (‪.)7‬‬\n                                          ‫‪ -2‬محضر القبض املرفق لفة (‪.)3‬‬\n                           ‫‪ -3‬التقرير الكيماوي الشرعي املرفق لفة (‪.)19‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n\n\n                                                                                    ‫‪194‬‬\n\f        ‫واملجــرم نظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n        ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n        ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات مــا أسن ــد إليــه واحلكم‬\n                                                                               ‫عليــه بالتالــي ‪:‬‬\n        ‫‪.1‬العقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n                                  ‫املخــدرات واملؤثــرات العقليــة لقــاء مــا أســند إليــه‪.‬‬\n        ‫‪.2‬إبعــاده مــن اململكــة بعــد تنفيــذ العقوبــة اســتناد ًا للفقــرة (‪ )2‬مــن املــادة‬\n                                                                       ‫(‪ )56‬مــن ذات النظــام‪.‬‬\n                                ‫‪.3‬عقوبة تعزيرية لقاء تستره على مصدر املخدرات‪.‬‬\n        ‫هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن‬\n        ‫هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـاً‪ :‬صحيــح‬\n        ‫مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض ومــن حيازتــي لقطعــة‬\n        ‫احلشــيش املخــدر البالــغ وزنهــا جــرام وخمســة أعشــار اجلــرام بقصــد‬\n        ‫التعاطــي ومــن اســتعمالي للحشــيش املخــدر وصحيــح اعتــرايف وغيــر‬\n        ‫صحيــح تســتري علــى مصــدر املخــدرات فقــد أخبــرت جهــة التحقيــق‬\n        ‫أننــي اشــتريتها مــن شــخص ال أعرفــه هكــذا أجــاب ثــم جــرى ســؤال‬\n        ‫املدعــي العــام هــل لديــه بينــة علــى مــا نفــاه املدعــى عليــه فقــال ‪ :‬ليــس‬\n        ‫ـدي ســوى مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب‬           ‫لـ َّ‬\n        ‫فجــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪ :‬التقريــر الكيمــاوي‬\n        ‫الشــرعي الصــادر مــن قســم الكيميــاء الشــرعية باملركــز اإلقليمــي‬\n        ‫ملراقبــة الســموم التابــع للمديريــة العامــة للشــؤون الصحيــة باملنطقــة‬\n      ‫الشــرقية برقــم () لعــام  ‪1434‬ه ـ املتضمــن إيجابيــة عي ــنة مــا ضبــط  ‬\n        ‫للحشــيش املخــدر كمــا  جــرى االطــاع علــى كــرت ســوابق املدعــى‬\n\n\n‫‪195‬‬\n\f  ‫عليــه املتضمــن خلــوه مــن الســوابق كمــا جــرى االطــاع علــى مذكــرة‬\n  ‫إيقــاف املدعــى عليــه املتضمنــة أنه أوقف بتاريــخ ‪1434/06/09‬هـ  فبناء‬\n  ‫علــى مــا ورد مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه‬\n  ‫والتأكــد مــن أهليتــه  وملــا ورد يف محضــر القبــض واعتــراف املدعــي‬\n  ‫عليــه ومبــا أنــه  صــادق علــى صحــة مــا نســب إليــه مــن  حيــازة  احلشــيش‬\n     ‫املخــدر علــى صفــة مــا ورد يف الدعــوى ومبــا أن مــا صــدر منــه حــرام‬\n‫يف الشــريعة ملــا يف  احلشــيش املخــدر مــن اخلطــر و الضــرر علــى  البــاد  ‬\n  ‫والعبــاد وعلــى مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي‬\n  ‫حــرم اهلل إال باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا) ممــا‬\n  ‫يســتوجب معاقبــة املدعــى عليــه  وتعزيــزه بالعقوبــة الــواردة يف املــادة‬\n  ‫الواحــدة واألربعــن مــن نظــام مكافحــة املخــدرات ويتوجــه أن يكــون‬\n  ‫أقــل عقوبــة  ملــا ظهــر مــن حالــه مــن النــدم  وألنــه ال ســوابق لــه ولقلــة‬\n  ‫الكميــة التــي وجــدت بحيازتــه  كمــا يتوجــه تخفيــف تلــك العقوبــة‬\n  ‫أيضــا حســب مقتضــى املــادة  الســتني  مــن النظــام نفســه ملــا ظهــر مــن‬\n  ‫حالــه حيــث أقــر بشــراء مــا مت ضبطــه مــن شــخص ال يعرفــه وحيازتهــا‬\n  ‫الســتعماله الشــخصي كمــا أقــر بتعاطيــه للحشــيش املخــدر يف الســابق‬\n  ‫مــن  النــدم ولظروفــه االجتماعيــة التــي اقتنعــت بهــا احملكمــة  وألنــه ال‬\n  ‫ســوابق لــه كمــا يتوجــه اســتحقاقه للعقوبــة الــواردة يف املــادة السادســة‬\n  ‫أن املدعــى عليــه أقـ َّـر باســتعمال‬‫واخلمســن الفقــرة الثانيــة منهــا ومبــا َّ‬\n  ‫احلشــيش املخــدر واســتعماله يأخــذ حكــم املســكر للتوافــق بينهمــا يف‬\n  ‫منــاط  احلكــم وحــد املســكر أن يجلــد صاحبــه ثمانــن جلــدة علنــا‬\n  ‫ـتقر عليــه عمــل األمــة ممــا يتوجــب حــد املدعــى عليــه حــد‬     ‫كمــا اسـ َّ‬\n  ‫أن املدعــى عليــه أنكــر‬   ‫املســكر الســتعماله للحشــيش املخــدر ومبــا َّ‬\n\n                                                                                         ‫‪196‬‬\n\f      ‫دعــوى املدعــي العــام باتهامــه بالتســتر علــى مصــدر املخــدرات وال بينــة‬\n      ‫للمدعــي العــام علــى ذلــك ممــا يســتوجب ر َّد دعــوى املدعــي العــام بإثبــات‬\n      ‫إدانــة املدعــى عليــه بذلــك  لــذا كلــه وألجــل احلــق العــام حكمــت علــى‬\n      ‫ـدي إدانــة املدعــى عليــه باســتعمال‬ ‫املدعــى عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n      ‫احلشــيش املخــدر ويجلــد حــد املســكر ثمانــن جلــدة دفعــة واحــدة علنـاً‪.‬‬\n      ‫ثانيـ ًا ‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة احلشــيش املخــدر املوصــوف‬\n      ‫يف  الدعــوى البالــغ وزنهــا غــرام وخمســة أعشــار اجلــرام بقصــد التعاطــي‬\n      ‫وأن يعــزر بســجنه شــهرين مــن تاريــخ توقيفــه علــى ذمــة القضيــة  وذلــك‬\n      ‫مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة املخــدرات‬\n      ‫واملــادة الســتني ‪ .‬ثالث ـ ًا ‪ /‬وأن يبعــد عــن اململكــة بعــد تنفيــذ العقوبــة‬\n      ‫احملكــوم بهــا عليــه واســتيفاء مــا لــه ومــا عليــه مــن حقــوق وال يســمح‬\n      ‫لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة حســب‬\n      ‫مقتضــى مــا ورد يف املــادة السادســة واخلمســن مــن النظــام نفســه الفقــرة‬\n      ‫ـدي إدانــة املدعــى عليــه بالتســتر علــى مصــدر‬‫الثانيــة ‪ .‬رابعـ ًا ‪ /‬لــم يثبــت لـ َّ‬\n      ‫املخــدرات وقــررت ر َّد دعــوى املدعــي العــام بإثبــات إدانتــه بذلــك وبتــاوة‬\n      ‫احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه يف االســتئناف قــرر‬\n      ‫قناعتــه باحلكــم وطلــب املدعــي العــام  رفــع احلكــم لالســتئناف وأن‬\n      ‫الئحتــه االعتراضيــة هــي الئحــة الدعــوى هــذا وجــرى توجيــه املدعــى‬\n      ‫عليــه   مبــا يلــزم ومــن ذلــك حرمــة اســتعمال احلشــيش املخــدر  وأثــره‬\n      ‫الســيئ علــى العقــل واملــال وأقفلــت اجللســة الســاعة الواحــدة وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن  حــرر احلكــم يف‬\n                                                                      ‫‪1434/07/17‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ففــي يــوم‬\n\n\n‫‪197‬‬\n\f  ‫االحــد ‪1434/08/28‬ه ـ فتحــت اجللســة الثانيــة الســاعة الواحــدة‬\n  ‫والنصــف وقــد عــادت املعاملــة املتعلقــة بالدعــوى العامــة ضــد‪ ......‬أردنــي‬\n  ‫اجلنســية مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب خطــاب‬\n  ‫فضيلــة رئيســها ذي الرقــم ‪ ......‬وتاريــخ ‪1434/08/15‬ه ـ وبرفقهــا قــرار‬\n  ‫الدائــرة اجلزائيــة االولــى (ج‪ )1/‬برقــم  وتاريــخ ‪1434/08/08‬هـ املتضمن‬\n  ‫مــا نصــه ‪ :‬لوحــظ أن فضيلتــه لــم يذكــر اســم املدعــى عليــه وجنســيته‬\n  ‫يف القــرار وصــورة ضبطــه  ملالحظــة مــا ذكــر وإكمــال الــازم ومــن‬\n  ‫ثــم إعــادة املعاملــة واهلل املوفــق أ‪.‬ه ـ عليــه أجيــب مشــايخي نفعنــي اهلل‬\n  ‫بعلمهــم بأنــه مت إكمــال الــازم حيــال القــرار صــورة الضبــط وأمــرت‬\n  ‫بالتهميــش علــى قــرار احلكــم مبــا طــرأ ومــن ثــم إعــادة املعاملــة حملكمــة‬\n  ‫االســتئناف باملنطقــة الشــرقية لتدقيــق احلكــم وأقفلــت اجللســة يف متــام‬\n  ‫الســاعة الثانيــة  وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫أجمعــن حــرر يف ‪1434/08/28‬ه ـ ِ‬\n  ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n  ‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n  ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n‫برقــم ‪ ......‬وتاريــخ ‪1434/9/15‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪  ......‬‬\n  ‫وتاريــخ ‪1434/9/21‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n  ‫باحملكمــة الشــيخ املســجل برقــم ‪ ......‬وتاريــخ ‪1434/7/17‬ه ـ اخلــاص‬\n  ‫بدعــوى‪ ......‬املدعــى العــام ضــد‪ ......‬اردنــي اجلنســية يف قضيــة مخــدرات‬\n  ‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n  ‫حيــث ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع علــى مــا أجــاب‬\n  ‫بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا‬\n\n\n                                                                                           ‫‪198‬‬\n\f      ‫رقــم ‪ ......‬يف ‪1434/8/8‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد االجــراء‬\n      ‫االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                          ‫حــرر يف ‪1434/11/5‬ه ـ‬\n\n\n\n\n‫‪199‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":192,"source_page_end":199,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"005f29a4fd10e71d828168910234450d527280f20e6f5c6e722753cee010af56","normalized_text_hash":"381ef1c402e7ff774fb756187702aed4a659c05969b3fbd7108f8dfe87a42e36","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p192-34270509"},{"id":"3adda0c8-985e-506e-bb18-b0b8d1dda9a2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واملنع من السفر.","document_number":"34269807","case_number":"34328434","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/16","year":"1434","subject":"مخدرات -تعاطي مخدرات -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪  34269807 :‬تاريخه ‪1434/7/16:‬هـ‬\n                    ‫رقم الدعوى‪34328434 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n        ‫‪      34297214‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطي‬\n                      ‫احلشــيش ‪ -‬التعزير بالســجن واملنع من الســفر‪.‬‬\n\n\n\n\n‫‪ .1‬ـ ـ قــول النبــي صلــى اهلل عليــه وســلم ‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                         ‫حرام ) رواه مســلم‪.‬‬\n‫‪ .2‬ـ ـ مــا ذكــره شــيخ اإلســام ـ ـ رحمــه اهلل ـ ـ يف الفتــاوى ‪ :‬أن احلشــيش‬\n                 ‫يعتبــر مــن املســكرات ‪ ،‬وهــو أصــح أقــوال أهــل العلــم‪.‬‬\n      ‫‪ .3‬ـ ـ املادة (‪ ) 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n       ‫‪ .4‬ـ املادة (‪ ) 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n       ‫‪ .5‬ـ املادة (‪ ) 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى العــام علــى املدعــى عليــه  بحيــازة ســيجارة ملفوفــة مــن‬\n‫احلشــيش املخــدر‪ ،‬وتعاطــي احلشــيش املخــدر وطلــب املدعــي العــام تعزيــر‬\n‫املدعــى عليــه بالســجن واملنــع مــن الســفر تطبيقـ ًا ألحــكام املــواد أرقــام‬\n‫(‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات ومعاقبتــه لقــاء تعاطيــه‬\n‫احلشــيش املخــدر ‪،‬حيــث أنــه أثنــاء قيــام الدورية الرســمية بعملهــم املعتاد‬\n‫شــوهدت ســيارة املدعــى عليــه فتــم إيقافهــا وشــوهد ســائقها يرمــي شــيئا‬\n\n                                                                                     ‫‪200‬‬\n\f      ‫مــا بجانــب الســيارة وبالتقاطهــا اتضــح أنهــا ســيجارة ملفوفــة يشــتبه أن‬\n      ‫تكــون مــن احلشــيش املخــدر‪ ،‬صــادق املدعــى عليــه مبــا هــو منســوب‬\n      ‫إليــه‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامة حد املســكر عليه‬\n      ‫وبتعزيــر املدعــى عليــه بالســجن واملنــع مــن الســفر ومت النــزول عــن احلــد‬\n      ‫األدنــى للعقوبــة بنــاء علــى املــادة (‪ ) 60‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة لعــدم وجــود ســوابق بحــق املدعــى عليــه‪  ،‬وأوصــت‬\n      ‫احملكمــة بعــاج املدعــى عليــه يف أحــد املصحــات يف عــاج اإلدمــان‬\n      ‫ملــدة ســنة وإخضاعــه جللســات ســلوكية وإرشــادية ‪ ،‬وقــرر املدعــى العــام‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة ‪ ،‬فيمــا قنــع املدعــى عليــه مبا صدر‬\n                 ‫بحقــه مــن حكــم‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بتبــوك برقــم  وتاريــخ ‪1434/07/16‬ه ـ املقيدة باحملكمة برقم‬\n      ‫‪  ......‬وتاريخ ‪1434/07/16‬هـ  ففي يوم  األحد املوافق ‪1434/07/16‬هـ‬\n      ‫افتتحت اجللســة الســاعة ‪02 : 00‬وفيها حضر املدعي العام ‪......‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......‬مبوجــب خطــاب التكليــف‬\n      ‫رقــم ‪  ......‬وتاريــخ ‪1431/7/14‬ه ـ وادعــى علــى احلاضــر معــه يف املجلــس‬\n      ‫الشــرعي  ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪  ......‬قائــا‬\n      ‫يف دعــواه أنــه  ورد باحملضــر املعــد مــن قبــل الفرقــة القابضــة بــاإلدارة‬\n      ‫العامــة ملكافحــة املخــدرات مبنطقــة تبــوك أنــه بتاريــخ ‪1431/6/16‬ه ـ‬\n      ‫وأثنــاء قيامهــم بعملهــم املعتــاد بحــي ‪ ......‬شــوهدت ســيارة مــن نــوع ‪.....‬‬\n\n‫‪201‬‬\n\f  ‫ومت توجيــه الدوريــة الرســمية الســتيقافها وعنــد ذلــك شــوهد ســائقها‬\n  ‫يرمــي شــيئا مــا بجانــب الســيارة وبالتقاطــه اتضــح أنهــا نصــف ســيجارة‬\n  ‫ملفوفــة يشــتبه أن تكــون حشــيش مخــدر بلــغ وزنهــا ‪ 360‬ملجــم وقــد‬\n  ‫اعتــرف أمــام الفرقــة بأنهــا لــه وقــد قــام برميهــا عنــد النــزول مــن الســيارة‬\n  ‫وبطلــب إثباتــه اتضــح أنــه املدعــى عليــه ومت اصطحــاب املذكــور‬\n  ‫إلــى مقــر اإلدارة إلكمــال الــازم معــه وبســماع أقــوال املدعــى عليــه‬\n  ‫اعتــرف بحيــازة مبــا مت ضبطــه معــه مــن نصــف ســيجارة ملفوفــة مــن‬\n  ‫احلشــيش املخــدر بلــغ وزنهــا ‪ 360‬ملجــم بقصــد التعاطــي وتعاطيــه مــن‬\n  ‫ذات الكميــة املضبوطــة وتعاطيــه الســابق للحشــيش املخــدر وقــد أثبــت‬\n  ‫التقريــر الكيميائــي الشــرعي رقــم لعــام ‪1431‬ه ـ والصــادر مــن مركــز‬\n  ‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بصحــة تبــوك إيجابيــة‬\n  ‫مســتخلص العينــة للحشــيش املخــدر وهــو مــن املــواد املخــدرة اخلاضعــة‬\n  ‫للرقابــة واملنــوه عنــه باجلــدول األول فئــة أ بتعميــم صاحــب الســمو‬\n‫امللكــي وزيــر الداخليــة رقــم ‪ 89400/19‬وتاريــخ ‪1426/10/25‬هــ  ‬\n  ‫وقــد أســفر التحقيــق معــه بحيــازة نصــف ســيجارة ملفوفــة ومخلوطــة‬\n  ‫مبــادة احلشــيش املخــدر بلــغ وزنهــا ‪ 360‬ملجــم بقصــد التعاطــي وتعاطيــه‬\n  ‫مــن ذات الكميــة املضبوطــة وتعاطيــه الســابق للحشــيش املخــدر وذلــك‬\n  ‫لألدلــة والقرائــن التاليــة ‪ -1‬مــا تضمنــه اعترافــه املنــوه عنــه واملــدون‬\n  ‫بالصفحــة رقــم ‪ 3-2‬مــن دفتــر احلقيــق اللفــة رقــم (‪ -2 )1‬محضــر‬\n  ‫القبــض والتفتيــش املنــوه عنــه واملــدون علــى الصفحــة رقــم ‪ 1‬مــن اللفــة‬\n  ‫رقــم (‪ -3 )1‬التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق باللفــة‬\n  ‫رقــم (‪ )13‬وحيــث أن مــا أقــدم عليــه املذكــور فعــل محــرم شــرعا‬\n  ‫ومعاقــب عليــه نظامــا اســتنادا للمــادة الثالثــة الفقــرة الثانيــة مــن نظــام‬\n\n\n                                                                                            ‫‪202‬‬\n\f        ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n        ‫رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب ‪ -1‬إثبــات مــا أســند إليــه‬\n        ‫‪-2‬احلكــم عليــه بالســجن لقــاء مــا أســند إليــه اســتنادا للمــادة ‪41‬‬\n        ‫الفقــرة ‪ 1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه‬\n        ‫أعــاه ‪ -3‬احلكــم مبنعــه مــن الســفر خــارج اململكــة اســتنادا للمــادة‬\n        ‫‪ 56‬الفقــرة ‪ 1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار‬\n        ‫إليــه أعــاه ‪ -4‬احلكــم عليــه باملقتضــى الشــرعي لقــاء تعاطيــه مــن ذات‬\n      ‫الكميــة املضبوطــة وتعاطيــه الســابق للحشــيش املخــدر هــذه دعــواي  ‬\n        ‫وبعــرض الدعــوى علــى املدعــى عليــه وســؤاله عنهــا أجــاب بقولــه مــا‬\n        ‫جــاء يف دعــوى املدعــي العــام مــن أنــي قمــت بتعاطــي احلشــيش املخــدر‬\n        ‫وأنــي حــزت نصــف ســيجارة ملفوفــة مخلوطــة مبــادة احلشــيش املخــدر‬\n        ‫بلــغ وزنهــا ‪ 360‬ملجــم بقصــد التعاطــي صحيــح وأنــا تائــب مــن تعاطــي‬\n        ‫املخــدرات هــذه إجابتــي  وباالطــاع علــى التقريــر الكيميائــي الشــرعي‬\n        ‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة  الشــرعية‬\n        ‫التابــع للشــؤون الصحيــة مبنطقــة تبــوك وجدتــه يتضمــن إيجابيــة مــا‬\n        ‫مت ضبطــه مــع املدعــى عليــه للحشــيش املخــدر وجــرى االطــاع علــى‬\n        ‫صحيفــة ســوابق املدعــى عليــه علــى اللفــة رقــم ‪ 13‬فوجدتهــا خاليــة مــن‬\n        ‫الســوابق هكــذا تضمنــت فبنــاء علــى الدعــوى واإلجابــة باملصادقــة على‬\n        ‫كل مــا جــاء يف الدعــوى وألن النبــي صلــى اهلل عليــه وســلم قــال كل‬\n        ‫مســكر خمــر وكل مســكر حــرام رواه مســلم وألن احلشــيش يعتبــر‬\n        ‫مــن املســكرات يف أصــح أقــوال أهــل العلــم هــو اختيــار شــيخ اإلســام‬\n        ‫بــن تيميــة  كمــا جــاء يف فتــاواه وبنــاء علــى اطالعــي علــى املادتــن‬\n        ‫(‪ )56-41‬مــن نظــام مكافحــة املخــدرات واطالعــي علــى املــادة ‪ 60‬مــن‬\n\n\n‫‪203‬‬\n\f    ‫نظــام مكافحــة املخــدرات ولكــون املدعــى عليــه ليــس لديــه ســوابق‬\n    ‫وقــرر توبتــه مــن تعاطــي املخــدرات لهــذا كلــه ثبــت لــدي إدانــة املدعــى‬\n    ‫عليــه بتعاطــي احلشــيش املخــدر وحيــازة نصــف ســيجارة مخلوطــة مبــادة‬\n    ‫احلشــيش املخــدر بلــغ وزنهــا ‪ 360‬ملجــم بقصــد التعاطــي وحكمــت عليــه‬\n    ‫مبــا يلــي  أوال جلــد املدعــى عليــه  ثمانــن جلــدة دفعــة واحــدة حــدا علنــا‬\n    ‫لقــاء تعاطيــه احلشــيش املخــدر ثانيــا تعزيــر املدعــى عليــه بســجنه ثالثــة‬\n    ‫أشــهر يحتســب منهــا مــدة إيقافــه لقــاء حيازتــه احلشــيش املخــدر ثالثــا‬\n    ‫منــع املدعــى عليــه مــن الســفر خــارج اململكــة العربيــة الســعودية مــدة‬\n    ‫ســنتني تبــدأ مــن تاريــخ انتهــاء مــدة ســجنه وأوصــي بعــاج املدعــى عليــه‬\n    ‫يف أحــد املصحــات املتخصصــة يف عــاج اإلدمــان خــال مــدة ســجنه  مــع‬\n    ‫إخضاعــه جللســات ســلوكية وإرشــادية وبعــرض احلكــم علــى املدعــى‬\n    ‫عليــه قنــع بــه وبعــرض احلكــم علــى املدعــي العــام لــم يقنــع بــه وطلــب‬\n    ‫رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه‬\n    ‫لطلبــه وعليــه جــرى رفــع اجللســة بعــد افتتاحهــا بنصــف ســاعة وحــرر يف‬\n            ‫يــوم االثنــن ‪1433/6/23‬ه ـ وصلــى اهلل وســلم علــى رســول اهلل‪.‬‬\n    ‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة‬\n    ‫الثانيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة‬\n‫مــن احملكمــة اجلزائيــة بتبــوك برقــم  وتاريــخ ‪1434/7/30‬هــ  املرفــق  ‬\n    ‫بهــا القــرار رقــم وتاريــخ ‪1434/7/16‬ه ـ ـ الصــادر مــن فضيلــة القاضــي‬\n‫اخلــاص بدعــوى املدعــي العــام  ضــد يف قضية حيازة واســتعمال مخدرات    ‬\n    ‫علــى النحــو املوضــح يف القــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n    ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وبنــاء‬\n    ‫علــى أن االجتهــاد ال ينقــض مبثلــه لذلــك قررنــا املصادقــة علــى احلكــم‬\n\n\n                                                                                          ‫‪204‬‬\n\f      ‫يف صلــب احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪205‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":200,"source_page_end":205,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c7e6a571bf438f6ef96108352b29c0c769dfb24733010dbbf6504615495075d3","normalized_text_hash":"7a5279a38c2da5daef916fba956d7f319e40f749cd94eca87de5112fff5c5fcc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p200-34269807"},{"id":"7ec01e68-08f7-5038-b9b0-9f7098a43738","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -إقرار املدعى عليه -حد املسكر -التعزير باملنع من السفر .","document_number":"34333624","case_number":"34417875","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/19","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -إقرار املدعى عليه -حد املسكر -التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪  34333624 :‬تاريخه ‪1434/10/19:‬هـ‬\n                    ‫رقم الدعوى‪34417875 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n  ‫تاريخه ‪1434/11/26:‬هـ‬         ‫‪34372117‬‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬إقــرار‬\n           ‫املدعــى عليــه ‪ -‬حــد املســكر ‪ -‬التعزيــر باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n‫‪1 .1‬قولــه تعالــى (يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n  ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون) ‪.‬‬\n‫‪2 .2‬قــول النبــي صلــى اهلل عليــه وســلم ‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                                     ‫حــرام ) ‪.‬‬\n‫‪3 .3‬مــا ذكــره شــيخ اإلســام ـ ـ رحمــه اهلل ـ ـ يف الفتــاوى (‪ ) 423/ 3‬أن‬\n                                 ‫عقوبــة متعاطــي احلشــيش حديــة ‪.‬‬\n‫‪4 .4‬قــرار هيئــة كبــار العلمــاء رقــم ‪ 53‬يف ‪ 1397/4/4‬هـ ـ مــن أن حــد‬\n‫شــرب املســكر ثمانــن جلــدة ‪ ،‬وهــو مذهــب جماهيــر أهــل العلــم ‪.‬‬\n       ‫‪5 .5‬املادة (‪ ) 2/ 3‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n         ‫‪6 .6‬املادة (‪ ) 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪7 .7‬املادة (‪ ) 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪8 .8‬املادة (‪ ) 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                         ‫‪9 .9‬املادة (‪ ) 128‬من نظام اإلجراءات اجلزائية ‪.‬‬\n                        ‫‪1010‬املادة ( ‪ ) 131‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n                                                                                      ‫‪206‬‬\n\f      ‫ادعــى املدعــى العــام علــى املدعــى عليــه بتعاطــي احلشــيش املخــدر‪ ،‬طلــب‬\n      ‫املدعــي العــام تعزيــر املدعــى عليــه بالســجن واملنــع مــن الســفر تطبيق ـ ًا‬\n      ‫ألحــكام املــواد أرقــام (‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات‪،‬‬\n      ‫حيــث قبــض علــى املدعــى عليــه إثــر تعاطــي احلشــيش املخــدر ‪،‬كما أقر‬\n      ‫املدعــى عليــه مبــا نســب إليــه‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n      ‫بحــد املســكر علــى املدعــى عليــه وتعزيــره باملنــع مــن الســفر ورد طلــب‬\n      ‫املدعــي العــام تطبيــق املــادة (‪ ) 41‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة بحقــه لعــدم انطباقهــا بحقــه وقــرر املدعــى العــام‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة‪ ،‬فيمــا قنــع املدعــى عليــه مبــا صــدر‬\n                  ‫بحقــه مــن حكــم وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬رئيــس احملكمــة اجلزائيــة‬\n      ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ ....‬وتاريــخ‬\n      ‫‪1434/09/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ ....‬وتاريخ‪1434/09/09‬ه ـ‬\n      ‫ففــي يــوم االثنــن املوافق‪1434/10/19‬ه ـ حضــر املدعــي العــام ‪....‬‬\n      ‫كمــا حضــر املدعــى عليــه  ‪ ،...‬ســعودي رقــم ســجله املدنــي(‪ )...‬وقــدم‬\n      ‫األول الئحــة دعــوى تتضمــن بــأن املدعــى عليــه ‪ ...‬البالــغ مــن العمــر(‪)21‬‬\n      ‫عام ـاً‪ ،‬غيــر محصــن‪ ،‬متعلــم‪ ،‬قبــض عليــه بتاريــخ ‪1434/4/24‬هــ‪،‬‬\n      ‫وأفــرج عنــه بتاريــخ ‪1434/4/25‬هــ‪ .‬وأنــه بتاريــخ ‪1434/4/24‬ه ـ مت‬\n      ‫القبــض علــى املدعــى عليــه إثــر مرافقتــه للمدعــو‪ ...‬واملدعــو‪ ...‬واللذيــن‬\n\n‫‪207‬‬\n\f‫اشــتركا بترويــج   قطعــة مــن احلشــيش املخــدر تــزن (‪ )21‬واحــد‬\n‫وعشــرين جراماً(فــرزت أوراق لهمــا كونهمــا موقوفــان بســجن اجلبيــل)‪.‬‬\n‫وباســتجوابه أفاد أنه يف يوم األربعاء املوافق‪1434/4/24‬هـ قبض عليه‬\n‫مــن قبــل رجــال مكافحــة املخــدرات اثــر مرافقتــه للمدعــو ‪ ...‬واملدعــو‪...‬‬\n‫وال يعلــم عــن األســباب وأنــه كان يتعاطــى احلشــيش املخــدر منــذ ســنه‬\n‫وتوقــف عــن تعاطيــه قبــل القبــض عليــه بشــهر ونصــف‪ .‬وقــد أســفر‬\n‫التحقيــق عــن اتهامــه بتعاطــي احلشــيش املخــدر املجــرم وفقـ ًا للفقــرة(‪)2‬‬\n‫مــن املادة(‪)3‬مــن نظــام مكافحــة املخــدرات‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫املوضحــة بالالئحــة وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى‬\n‫ســوابق مســجله‪ .‬وحيــث إن مــا أقــدم عليــه املذكور وهــو بكامل أهليته‬\n‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب‬\n‫إثبــات مــا أســند واحلكــم عليــه مبــا يلــي ‪-1 .:‬بعقوبــة الســجن الــواردة‬\n‫بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام‪-2 .‬منعــه مــن الســفر‬\n‫وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن النظــام‪ .‬هــذه دعــواي‬\n‫ا مــا ذكــره املدعــي العــام مــن‬   ‫وبعرضهــا علــى املدعــى عليــه أجــاب قائـ ً‬\n‫اتهامــي بتعاطــي احلشــيش املخــدر صحيــح ولكننــي توقفــت عــن تعاطيــه‬\n‫قبــل ســنة تقريبـ ًا هكــذا أجــاب‪ .‬فجــرى ســؤاله هــل ســبق أن صــدر عليــه‬\n‫حكــم قضائــي بهــذا اخلصــوص فقــال ال ‪ ،‬وبســؤال الطرفــن ألديهمــا‬\n‫ـاء علــى مــا تقــدم‬‫مــا يريــدان إضافتــه فقــاال ليــس لدينــا مــا نضيفــه‪ .‬فبنـ ً‬\n‫وحيــث تتلخــص دعــوى املدعــي العــام يف اتهــام املدعــى عليــه بتعاطــي‬\n‫احلشــيش املخــدر ويطلــب إثبــات مــا أســند ومعاقبتــه عليــه ‪،‬وألن هــذه‬\n‫احملكمــة مختصــة بنظــر الدعــوى بنــاء علــى املــواد (‪ )131،128‬مــن‬\n‫نظــام اإلجــراءات اجلزائيــة وإلقــرار املدعــى عليــه وهــو بكامــل أهليتــه‬\n\n\n                                                                                         ‫‪208‬‬\n\f      ‫بتعاطــي احلشــيش املخــدر وألن مــا أقــدم عليــه فعــل محــرم شــرع ًا لقولــه‬\n      ‫تعالــى (( يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم‬\n      ‫رجــس مــن عمــل الشــيطان فاجتنبــوه )) املائــدة‪ 90 :‬ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم (( كل مس ــكر خمــر وكل خمــر حــرام )) رواه مســلم‪،‬‬\n      ‫كمــا أن تعاطــي احلشــيش املخــدر فعــل مجــرم نظام ـ ًا وفق ـ ًا للفقــرة‬\n      ‫(‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n      ‫ونظــر ًا ألن التهمــة ووقائــع الدعــوى ليــس فيهــا قيــام املدعــى عليــه‬\n      ‫بارتــكاب فعــل مجــرم ســوى تعاطــي احلشــيش املخــدر ‪،‬وبعــد االطــاع‬\n      ‫علــى املــواد (‪ )60، 56، 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ‪ ،‬وملــا ذهــب إليــه شــيخ اإلســام ابــن تيميــة مــن أن عقوبــة تعاطــي‬\n      ‫احلشــيش املخــدر حديــة انظــر الفتــاوى الكبــرى ( ‪، )423/3‬و ملــا نــص‬\n      ‫عليــه جماهيــر أهــل العلــم مــن أن حــد شــرب املســكر ثمانــن جلــدة‬\n      ‫وهــو مــا انتهــى إليــه قــرار هيئــة كبــار العلمــاء باململكــة ذي الرقــم رقــم‬\n      ‫‪53‬يف ‪1397/4/4‬هــ  فقــد حكمــت باآلتــي‪ :‬أوالً‪ :‬إدانــة املدعــى عليــه‬\n      ‫احلاضــر ‪ ....‬بتعاطــي احلشــيش املخــدر‪ .‬ثانيـاً‪ :‬جلــده حــد شــرب املســكر‬\n      ‫ثمانــن جلــدة دفعــة واحــدة علنـ ًا ومنعــه مــن الســفر خــارج اململكــة مــدة‬\n      ‫ســنتني تبــدأ بعــد اكتســاب احلكــم القطعيــة‪ .‬ثالث ـاً‪ :‬رد طلــب املدعــي‬\n      ‫العــام احلكــم بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )41‬مــن النظــام لعــدم انطباقهــا بحــق املدعــى عليــه‪ .‬وبإعــان احلكــم‬\n      ‫قنــع بــه املدعــى عليــه وقــرر املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة‬\n      ‫حملكمــة االســتئناف دون تقــدمي الئحــة اعتراضيــة ‪ ،‬وصلــى اهلل علــى‬\n                                           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬رئيــس احملكمــة اجلزائيــة مبحافظة‬\n\n\n‫‪209‬‬\n\f  ‫القطيــف فقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n  ‫الشــرقية وبرفقهــا القــرار رقــم ‪ ...‬يف ‪1434/11/26‬ه ـ املتضمــن‬\n             ‫املصادقــة علــى احلكــم و للبيــان أحلــق يف ‪1434/12/18‬ه ـ ‪.‬‬\n  ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n  ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف الشــيخ‪  ....‬‬\n  ‫برقــم‪   ...‬وتاريــخ ‪1434/10/22‬ه ـ املقيــدة لــدى احملكمــة برقــم‪...‬‬\n  ‫وتاريــخ ‪1434/10/28‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه‬\n  ‫املســجل برقــم‪ ...‬وتاريــخ ‪1434/10/19‬ه ـ اخلــاص بدعــوى‪ ......‬املدعــي‬\n  ‫العــام  ضــد‪  .....‬يف قضيــة مخــدرات  وقــد تضمــن القــرار حكــم فضيلتــه‬\n  ‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n  ‫املعاملــة قررنــا املصادقــه علــى احلكــم  واهلل املوفــق وصلــى اهلل علــى‬\n               ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/11/26‬ه ـ‬\n\n\n\n\n                                                                                           ‫‪210‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":206,"source_page_end":210,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0d6a11ff9305dbe40e3befdb56f518f3d97428c7eaa2cf55f2f4d8814a0d0ede","normalized_text_hash":"f75bb58f071b49b02600bcb71ad1ee9a9217bbd5782163c41cc6298cfa4de4f1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p206-34333624"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

